import json, csv, html, os
import sys
D=sys.argv[1] if len(sys.argv)>1 else os.environ.get('OUTREACH_DIR', os.path.expanduser('~/Desktop/Outreach_2026-10-14')); rows=json.load(open(f'{D}/tracker_rows.json'))
cols=['company','role','loc','arr','type','pay','posted','skills','visa','recruiter','contact','link','fit','resume','msg','status']
heads=['Company / Agency','Job title','Location','Arrangement','C2C / W2 / FTE','Pay','Posted','Main skills','Work auth / TN','Recruiter','Public contact','Listing / post','Fit','Resume version','Message file','Status']
sent=[r for r in rows if r['status'].startswith('SENT')]; ns=[r for r in rows if not r['status'].startswith('SENT')]
def table(rs): return '<table><thead><tr>'+''.join(f'<th>{h}</th>' for h in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td class="{c}">{html.escape(str(r.get(c,"")))}</td>' for c in cols)+'</tr>' for r in rs)+'</tbody></table>'
style='@page{size:11in 8.5in;margin:0.4in} body{font:8.2px/1.3 -apple-system,Helvetica,Arial,sans-serif;color:#1b2a4a} h1{font-size:15px;margin:0 0 2px} h2{font-size:11px;margin:12px 0 4px;color:#2563eb} p{margin:2px 0 6px;font-size:8.5px;color:#4b5563} table{border-collapse:collapse;width:100%;table-layout:fixed} th{background:#1b2a4a;color:#fff;text-align:left;padding:3px;font-size:7.5px} td{border-bottom:1px solid #d1d5db;padding:3px;vertical-align:top;word-wrap:break-word} tr:nth-child(even) td{background:#f3f4f6} td.status{font-weight:600} th:nth-child(8),td.skills{width:11%} th:nth-child(11),td.contact{width:11%} th:nth-child(14),td.resume{width:9%} .legend{font-size:8px;color:#4b5563;margin-top:8px}'
intro=('Sources: LinkedIn recruiter posts (7-day sweep, then 24-hour contract sweep, then a 24-hour full-time sweep on 2026-10-14 evening: 12 queries, 64 posts, 25 with public emails, 3 US full-time React roles contacted), LinkedIn Jobs (direct-apply only, not contacted), Indeed (no recruiter emails), Google Groups C2C lists (subscribed 2026-10-14), and inbound recruiter emails in Aaron\'s inbox. "Not stated" = fact not published in the post; TN status was disclosed in every message and support asked where unclear. Nothing was submitted as a formal application. Resumes: ~/Desktop/Outreach_2026-10-14/resumes (PDF + editable .pages/.docx). Messages: ~/Desktop/Outreach_2026-10-14/messages.')
doc=f'<!doctype html><html><head><meta charset="utf-8"><title>Opportunity Tracker 2026-10-14</title><style>{style}</style></head><body><h1>Aaron Ramírez · React / React Native / Angular Outreach Tracker · 2026-10-14</h1><p>{intro}</p><h2>Sent ({len(sent)})</h2>{table(sent)}<h2>Reviewed, not sent ({len(ns)})</h2>{table(ns)}<p class="legend">Confirmed facts come from the post or email text; anything marked "Not stated", "assumed", or "asked" is unknown. No emails or phone numbers were guessed.</p></body></html>'
open(f'{D}/Opportunity_Tracker_2026-10-14.html','w').write(doc)
with open(f'{D}/Opportunity_Tracker_2026-10-14.csv','w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=cols+['src']); w.writeheader(); [w.writerow({k:r.get(k,'') for k in cols+['src']}) for r in rows]
print(len(sent),len(ns))
